<script setup>
import {onBeforeUnmount,reactive,ref,watch} from 'vue';
import {useAuthStore} from '../../stores/auth.js';
import {useRouter} from 'vue-router';
import {ElMessage} from 'element-plus';
import {roleLabels} from '../../../../src/shared/permissions.js';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';
import {prepareMobileAvatar} from '../../utils/mobile-evidence.js';
const auth=useAuthStore(),router=useRouter(),avatarInput=ref(),saving=ref(false),preparing=ref(false),changingPassword=ref(false),profileError=ref(''),passwordError=ref('');
const profile=reactive({name:'',avatar_url:''}),password=reactive({old_password:'',new_password:'',confirm_password:''});
let version=0,disposed=false;
function reset(){++version;Object.assign(profile,{name:auth.user?.name||'',avatar_url:auth.user?.avatar_url||''});Object.assign(password,{old_password:'',new_password:'',confirm_password:''});profileError.value='';passwordError.value='';}
watch(()=>`${auth.user?.id}:${auth.user?.tenant?.id}`,reset,{immediate:true});
async function chooseAvatar(event){const file=event.target.files?.[0];event.target.value='';if(!file||saving.value||preparing.value)return;const token=version,scope=currentApiCacheScope();preparing.value=true;profileError.value='';try{const url=await prepareMobileAvatar(file);if(!disposed&&token===version&&scope===currentApiCacheScope())profile.avatar_url=url;}catch(e){if(token===version&&scope===currentApiCacheScope())profileError.value=e.message;}finally{preparing.value=false;}}
async function saveProfile(){if(saving.value||preparing.value)return;if(!profile.name.trim())return ElMessage.warning('请填写姓名');const token=version,scope=currentApiCacheScope();saving.value=true;profileError.value='';try{await auth.updateProfile({name:profile.name.trim(),avatar_url:profile.avatar_url});if(!disposed&&token===version&&scope===currentApiCacheScope())ElMessage.success('个人资料已更新');}catch(e){if(e.name!=='AbortError'&&token===version&&scope===currentApiCacheScope())profileError.value=e.message;}finally{saving.value=false;}}
async function savePassword(){if(changingPassword.value)return;passwordError.value='';if(!password.old_password||!password.new_password)return passwordError.value='请填写当前密码和新密码';if(password.new_password.length<8)return passwordError.value='新密码至少需要8位';if(password.new_password!==password.confirm_password)return passwordError.value='两次输入的新密码不一致';const token=version,scope=currentApiCacheScope();changingPassword.value=true;try{await apiClient.post('/api/auth/change-password',{old_password:password.old_password,new_password:password.new_password});if(disposed||token!==version||scope!==currentApiCacheScope())return;Object.assign(password,{old_password:'',new_password:'',confirm_password:''});ElMessage.success('密码已修改，其他设备需重新登录');}catch(e){if(token===version&&scope===currentApiCacheScope())passwordError.value=e.message;}finally{changingPassword.value=false;}}
async function logout(){if(saving.value||changingPassword.value)return;await auth.logout();router.replace('/login');}
window.addEventListener('erp:auth-scope-changed',reset);onBeforeUnmount(()=>{disposed=true;++version;Object.assign(password,{old_password:'',new_password:'',confirm_password:''});window.removeEventListener('erp:auth-scope-changed',reset);});
</script>
<template><div class="mobile-account mobile-form">
 <section class="mobile-record mobile-profile"><div class="mobile-profile-heading"><el-avatar :src="profile.avatar_url" :size="64">{{(profile.name||'我').slice(0,1)}}</el-avatar><div><strong>{{auth.user?.username}}</strong><small>{{auth.user?.tenant?.name||'未选择企业'}} · {{roleLabels(auth.user)||'按企业授权'}}</small></div></div><input ref="avatarInput" type="file" accept="image/*" hidden @change="chooseAvatar"><div class="mobile-record-actions"><el-button :loading="preparing" :disabled="saving" @click="avatarInput.click()">更换头像</el-button></div><label>姓名<input v-model="profile.name" aria-label="姓名" maxlength="100" autocomplete="name" :disabled="saving"></label><el-alert v-if="profileError" :title="profileError" type="warning" :closable="false"/><el-button type="primary" :loading="saving" :disabled="preparing" @click="saveProfile">保存个人资料</el-button></section>
 <section class="mobile-record"><h3>修改密码</h3><label>当前密码<input v-model="password.old_password" aria-label="当前密码" type="password" autocomplete="current-password" :disabled="changingPassword"></label><label>新密码<input v-model="password.new_password" aria-label="新密码" type="password" autocomplete="new-password" :disabled="changingPassword"></label><label>确认新密码<input v-model="password.confirm_password" aria-label="确认新密码" type="password" autocomplete="new-password" :disabled="changingPassword"></label><el-alert v-if="passwordError" :title="passwordError" type="warning" :closable="false"/><el-button :loading="changingPassword" @click="savePassword">确认修改密码</el-button></section>
 <details class="mobile-record"><summary>添加到手机桌面</summary><p class="mobile-muted">苹果 Safari：分享 → 添加到主屏幕。安卓：浏览器菜单 → 安装应用或添加到主屏幕。</p></details><el-button :disabled="saving||changingPassword" @click="logout">退出登录</el-button>
</div></template>
<style scoped>.mobile-profile-heading{display:flex;align-items:center;gap:12px}.mobile-profile-heading>div{display:grid;gap:6px;min-width:0}.mobile-profile-heading small{color:var(--el-text-color-secondary)}.mobile-account summary{cursor:pointer;font-size:14px}.mobile-account label{display:grid;gap:7px}</style>
